 "content": "def transform(grid):
    # Demo pattern: recolor zero cells that are diagonal-connected to nearby 5s,
    # retaining the unassociated background. The diagonal component signatures
    # are selected by their local 5-neighbor count.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        z = (x + dx, y + dy)
                        if (dx or dy) and 0 <= z[0] < h and 0 <= z[1] < w and grid[z[0]][z[1]] == 0 and z not in seen:
                            seen.add(z)
                            stack.append(z)
            # Recolor only components that contain a zero cell fully surrounded
            # by 5 in its 8-neighborhood; color marks the pocket scale.
            qualifies = False
            for x, y in comp:
                neighbors = [(x+dx, y+dy) for dx in (-1,0,1) for dy in (-1,0,1) if dx or dy]
                inside = [(a,b) for a,b in neighbors if 0 <= a < h and 0 <= b < w]
                if len(inside) == 8 and all(grid[a][b] == 5 for a,b in inside):
                    qualifies = True
            if qualifies:
                color = 7 if len(comp) <= 4 else 8
                for x, y in comp:
                    out[x][y] = color
    return out
